// Some portions generated by Codex
package org.eclipse.rdf4j.http.server.protocol;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import org.eclipse.rdf4j.common.webapp.views.SimpleResponseView;
import org.eclipse.rdf4j.http.protocol.Protocol;
import org.eclipse.rdf4j.repository.manager.RepositoryDeletionPolicy;
import org.springframework.context.ApplicationContextException;
import org.springframework.web.servlet.ModelAndView;
import org.springframework.web.servlet.mvc.AbstractController;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

/**
 * Handles requests for protocol information. Currently returns the protocol version as plain text.
 *
 * @author Herko ter Horst
 */
public class ProtocolController extends AbstractController {
	private RepositoryDeletionPolicy deletionPolicy = RepositoryDeletionPolicy.disabled();

	public ProtocolController() throws ApplicationContextException {
		setSupportedMethods(METHOD_GET, METHOD_HEAD);
	}

	public void setRepositoryDeletionPolicy(RepositoryDeletionPolicy policy) {
		deletionPolicy = Objects.requireNonNull(policy);
	}

	@Override
	protected ModelAndView handleRequestInternal(HttpServletRequest request, HttpServletResponse response)
			throws Exception {
		Map<String, Object> model = new HashMap<>();
		response.setHeader(Protocol.REPOSITORY_DELETE_PASSWORD_REQUIRED_HEADER,
				Boolean.toString(deletionPolicy.isPasswordRequired()));
		model.put(SimpleResponseView.CONTENT_KEY, Protocol.VERSION);
		return new ModelAndView(SimpleResponseView.getInstance(), model);
	}
}
